using Microsoft.ML;
using Microsoft.ML.Data;
using TicketClassifier.Models;

namespace TicketClassifier.Services;

public class TicketModelService
{
    private readonly MLContext _mlContext = new(seed: 42);
    private ITransformer? _model;
    private string[] _categoryLabels = [];

    public MulticlassClassificationMetrics? Metrics { get; private set; }

    public string[] CategoryLabels => _categoryLabels;

    public string ModelPath { get; private set; } = string.Empty;

    public MulticlassClassificationMetrics TrainAndEvaluate(string dataPath, string modelOutputPath)
    {
        var data = _mlContext.Data.LoadFromTextFile<TicketInput>(
            dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

        var split = _mlContext.Data.TrainTestSplit(data, testFraction: 0.2, seed: 42);

        var pipeline = _mlContext.Transforms.Conversion.MapValueToKey("Label", "Category")
            .Append(_mlContext.Transforms.Text.FeaturizeText("SubjectFeatures", nameof(TicketInput.Subject)))
            .Append(_mlContext.Transforms.Text.FeaturizeText("DescriptionFeatures", nameof(TicketInput.Description)))
            .Append(_mlContext.Transforms.Concatenate("Features", "SubjectFeatures", "DescriptionFeatures", nameof(TicketInput.Priority)))
            .Append(_mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy("Label", "Features"))
            .Append(_mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

        _model = pipeline.Fit(split.TrainSet);

        var predictions = _model.Transform(split.TestSet);
        Metrics = _mlContext.MulticlassClassification.Evaluate(predictions);

        // Extract label names for confidence mapping
        var predData = _model.Transform(data);
        var scoreColumn = predData.Schema["Score"];
        var slotNames = new VBuffer<ReadOnlyMemory<char>>();
        scoreColumn.GetSlotNames(ref slotNames);
        _categoryLabels = slotNames.DenseValues().Select(v => v.ToString()).ToArray();

        // Save model to file for PredictionEnginePool
        ModelPath = modelOutputPath;
        _mlContext.Model.Save(_model, data.Schema, modelOutputPath);

        return Metrics;
    }

    public ITransformer GetModel() => _model ?? throw new InvalidOperationException("Model not trained");
}

