[HttpGet("metrics")]
public ActionResult GetMetrics()
{
    var metrics = _modelService.Metrics;
    if (metrics is null)
        return StatusCode(503, "Model not yet trained");

    return Ok(new
    {
        MicroAccuracy = double.IsNaN(metrics.MicroAccuracy) ? 0 : metrics.MicroAccuracy,
        MacroAccuracy = double.IsNaN(metrics.MacroAccuracy) ? 0 : metrics.MacroAccuracy,
        LogLoss = double.IsNaN(metrics.LogLoss) || double.IsInfinity(metrics.LogLoss) ? 0 : metrics.LogLoss,
        LogLossReduction = double.IsNaN(metrics.LogLossReduction) || double.IsInfinity(metrics.LogLossReduction) ? 0 : metrics.LogLossReduction
    });
}

